/* 02_ecl_engine.sas  ·  IFRS 9 lifetime ECL engine */
%macro ecl_engine(loans=, collat=, scen=, out=);
  proc sql;
    create table &out as
    select l.loan_id,
           /* scenario-weighted EAD x PD x LGD x discount */
           %ecl_core(l, c, s)  as lifetime_ecl_eur,
           %stage_alloc(l)     as stage_flag,
           %discount(l)        as discount_factor
    from &loans l
      left join &collat c on l.loan_id = c.loan_id
      cross join &scen  s
    group by l.loan_id;
  quit;
%mend;
%ecl_engine(loans=stg.loan_book, collat=stg.collateral,
            scen=risk.macro_scenarios, out=work.ecl_by_account);
